class Adventurer {
  constructor(name, health, maxCapacity) {
    this.name = name;
    this.health = health;
    this.position = { x: 0, y: 0 };
    // TODO: This class should not manage inventory directly.
    // Move inventory logic to a new 'Backpack' class.
    this.items = [];
    this.maxCapacity = maxCapacity;
  }

  move(direction) {
    if (direction === "north") this.position.y++;
    else if (direction === "south") this.position.y--;
    else if (direction === "east") this.position.x++;
    else if (direction === "west") this.position.x--;
    return `${this.name} moved to (${this.position.x}, ${this.position.y}).`;
  }

  // TODO: Move this method to the Backpack class and add input validation.
  addItem(item) {
    if (this.items.length < this.maxCapacity) {
      this.items.push(item);
      return `${item} added to inventory.`;
    } else {
      return `Inventory is full. Cannot add ${item}.`;
    }
  }

  // TODO: Move this method to the Backpack class.
  listItems() {
    if (this.items.length === 0) {
      return `${this.name}'s inventory is empty.`;
    }
    return `${this.name}'s inventory: ${this.items.join(', ')}`;
  }
}

