class Backpack {
  constructor(capacity) {
    this.items = [];
    this.capacity = capacity;
  }

  addItem(itemName) {
    // Input validation: item name cannot be empty or just whitespace
    if (!itemName || itemName.trim() === '') {
      return "Cannot add an empty or invalid item name to the backpack.";
    }
    if (this.items.length < this.capacity) {
      this.items.push(itemName.trim());
      return `${itemName.trim()} added to backpack.`;
    } else {
      return `Backpack is full. Cannot add ${itemName.trim()}.`;
    }
  }

  removeItem(itemName) {
    const index = this.items.indexOf(itemName);
    if (index > -1) {
      this.items.splice(index, 1);
      return `${itemName} removed from backpack.`;
    }
    return `${itemName} not found in backpack.`;
  }

  listItems() {
    if (this.items.length === 0) {
      return "Backpack is empty.";
    }
    return `Backpack contents (${this.items.length}/${this.capacity}): ${this.items.join(', ')}`;
  }
}

